/// <summary>
/// MPJ_17845_PBMSProductMDRItemSite
/// Extension of Purchtable form datasource of PurchLine
/// </summary>
[ExtensionOf(formDataSourceStr(PurchTable,PurchLine))]
final class METPurchTableFormPurchLineDs_Extension
{   

}

Method.Source:
     /// <summary>
    /// Update values when Item id on Purch line is modified
    /// </summary>
    void itemIdModified()
    {
        InventItemPurchSetup    metInventItemPurchSetup;
        PurchLine               metpurchLineStd         = this.formRun().dataSource().cursor() as PurchLine;
        FormDataSource          metDatasourceInventDim  = this.formRun().dataSource(formDataSourceStr(PurchTable,InventDim)) as FormDataSource;
        InventDim               metInventDimLoc         = metDatasourceInventDim.cursor() as InventDim;
        InventDim               metInventDimPurch;

        next itemIdModified();

        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        
        select firstonly METPurchUnit 
            from metInventItemPurchSetup
            where metInventItemPurchSetup.ItemId == metpurchLineStd.ItemId
            exists join metInventDimPurch
            where metInventDimPurch.inventDimId == metInventItemPurchSetup.InventDimId
            &&    metInventDimPurch.InventSiteId == metInventDimLoc.InventSiteId;

        if (metInventItemPurchSetup.METPurchUnit)
        {
            metpurchLineStd.PurchUnit  = metInventItemPurchSetup.METPurchUnit;
        }
        //MPJ_17845_PBMSProductMDRItemSite - End
    }

    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource              metPurchLine_ds;
        METPurchLine                metPurchLine;
        PurchLine                   purchLineLoc;

        // CB220_PlannerCodes
        // moved buyer code logic after sales line is successfully inserted and not before, made some adjustment to previous code
        // Identify if it's first PO line being inserted'
        boolean firstPOLine = false;

        purchLineLoc = this.cursor();
        if (!purchLineLoc.RecId && !purchLine::exist(purchLineLoc.purchid))
        {
            firstPOLine = true;
        }


        next write();

        metPurchLine_ds = this.formRun().dataSource(formDataSourceStr(PurchTable, METPurchLine));

        if (metPurchLine_ds)
        {
            purchLineLoc      = this.cursor();
            metPurchLine   = metPurchLine_ds.cursor();

            ttsbegin;
            METInventLocation metInventLocation = METInventLocation::findByInventLocationId(InventDim::find(purchLineLoc.InventDimId).InventLocationId);
            metPurchLine.PurchaseWMSFactor = METPurchTableFormEventHandler::processPurchaseWMSFactor(metInventLocation.ExternalWMSUnit, purchLineLoc);

            if (metPurchLine.PurchLine)
            {
                metPurchLine.selectForUpdate(true);
                metPurchLine.write();
            }
            ttscommit;
            purchLineLoc.metPackMETPurchLine(metPurchLine);
  
            //insert in correct order Parent, then extension
            metPurchLine.SysExtensionSerializerExtensionMap::insertAfterBaseTable(purchLineLoc);
        }

        // CB220_PlannerCodes
        // after successful insertion of the first PO line
        if (firstPOLine)
        {
            PurchTable purchTable = this.formRun().dataSource(formDataSourceStr(PurchTable, PurchTable)).cursor();

            ttsbegin;
            purchTable.selectForUpdate(true);
            
            // For manual PO, after the first PO line is saved, find buyer code from item coverage and update buyer code and orderer in PO header
            purchTable.METSetItemBuyerGroupId(purchLineLoc.ItemId);

            if(purchTable && purchTable.validateWrite())
            {
                purchTable.write();
            }
            ttscommit;
        }

    }

    /// <summary>
    /// VM - CB199 - Restrict PO & delete fields Disable fields based on Role.
    /// </summary>
    /// <returns>Boolean</returns>
    int  active()
    {
        boolean ret;

        ret = next active();

        FormDataSource purchLine_ds = this.formRun().dataSource(tableStr(purchLine));
        PurchLine purchLineLoc = this.cursor();

        if (PurchTable::find(purchLineLoc.PurchId).PurchaseType == PurchaseType::Purch 
            && !Global::isSystemAdministrator())
        {
            purchLine_ds.object(fieldNum(PurchLine,LineAmount)).allowEdit(NoYes::No);
            purchLine_ds.object(fieldNum(PurchLine,PurchPrice)).allowEdit(NoYes::No);
        }

        return ret;
    }
